import { Hono } from 'hono';
import type { Bindings } from '../types';

export const departmentsRoute = new Hono<{ Bindings: Bindings }>()

  // GET ALL DEPARTMENTS (3NF lookup table served to the SPA)
  .get('/', async (c) => {
    try {
      const { results } = await c.env.DB.prepare(
        `SELECT
           d.id,
           d.nama AS name,
           d.cross_partner_id AS crossPartnerId,
           d.ketua_jabatan AS ketuaJabatan,
           d.penolong_pegawai_aset AS penolongPegawaiAset,
           (SELECT COUNT(*) FROM locations l WHERE l.department_id = d.id) AS totalLokasi
         FROM departments d
         ORDER BY d.id ASC`
      ).all();

      return c.json({
        success: true,
        total: (results ?? []).length,
        data: results ?? [],
      });
    } catch (e: any) {
      return c.json(
        { success: false, message: 'Ralat mendapatkan senarai jabatan: ' + e.message },
        500
      );
    }
  });
